if([string]$amendment.status-ne'AUTHORIZED-VERSIONED-PRE-PILOT-DEFECT-REPAIR'-or[bool]$amendment.executionBoundary.formalCampaignAuthorized-ne$false-or[string]$amendment.upstreamDiagnosis.sha256-ne(Hash (Join-Path $ProjectPath $diagnosisRelative))){throw 'Attempt-15 amendment boundary/binding is invalid.'}
foreach($path in @((Join-Path $ProjectPath 'Research\FormalRuns\Gate13R_36h_10pct_4Lane\v1'),(Join-Path $ProjectPath 'Research\PilotRuns\Gate13R_36h_10pct_4Lane\v15'),(Join-Path $ProjectPath 'Research\Verification\Gate13R_36h_10pct_4Lane\v15'),'H:\DDM_Final_Project_Gate13R36H\v15')){if(Test-Path -LiteralPath $path){throw "Forbidden/create-new root already exists: $path"}}

