foreach($entry in $sources.GetEnumerator()){$source=Join-Path $ProjectPath ([string]$entry.Key);$destination=Join-Path $ProjectPath ([string]$entry.Value);$text=[IO.File]::ReadAllText($source);$upper=[regex]::Matches($text,[regex]::Escape('V14')).Count;$lower=[regex]::Matches($text,[regex]::Escape('v14')).Count;if(($upper+$lower)-lt1){throw "No active v14 identity found: $($entry.Key)"};$derived=$text.Replace('V14','V15').Replace('v14','v15');Write-NewText $destination $derived;Parse-PowerShell $destination;$derivations.Add([pscustomobject][ordered]@{sourceRelativePath=[string]$entry.Key;sourceSha256=Hash $source;destinationRelativePath=[string]$entry.Value;destinationSha256=Hash $destination;uppercaseRouteCount=$upper;lowercaseRouteCount=$lower;parserPassed=$true})}

