$plan.upstreamHashes.prePilotDefectRepairAmendment=Hash (Join-Path $ProjectPath $amendmentRelative);$plan.upstreamHashes|Add-Member -NotePropertyName attempt14Plan -NotePropertyValue (Hash $planV14Path);$plan.upstreamHashes|Add-Member -NotePropertyName attempt14DerivationFailure -NotePropertyValue (Hash (Join-Path $ProjectPath 'Research\Gate13R_36h_10pct_4Lane_Attempt14_Derivation_Failure.v1.json'));$plan.upstreamHashes|Add-Member -NotePropertyName attempt14DerivationManifest -NotePropertyValue (Hash (Join-Path $ProjectPath 'Research\Gate13R_36h_10pct_4Lane_Attempt14_Derivation_Partial_Manifest.v1.json'));$plan.upstreamHashes|Add-Member -NotePropertyName attempt14DepthDiagnosis -NotePropertyValue (Hash (Join-Path $ProjectPath $diagnosisRelative));$plan.upstreamHashes|Add-Member -NotePropertyName laneBootstrapRunnerV15 -NotePropertyValue (Hash (Join-Path $ProjectPath 'Research\Verification\Run-Gate13R36hLaneBootstrapCompileV15.ps1'))
Write-NewJson $planV15Path $plan 100
&'C:\Windows\System32\WindowsPowerShell\v1.0\powershell.exe' -NoProfile -ExecutionPolicy Bypass -File (Join-Path $ProjectPath 'Research\Verification\New-Gate13R36hPilotScheduleV15.ps1') -ProjectPath $ProjectPath;if($LASTEXITCODE-ne0){throw "V15 schedule generation failed with exit $LASTEXITCODE."}

