$provenance.preparationModule=Bound 'Research\Gate13R36hConcurrencyPreparationV15.psm1';$provenance.blockRunner=Bound 'Research\Run-Gate13R36hBlockV15.ps1';$provenance.telemetryRunner=Bound 'Research\Run-Gate13R36hTelemetryProbeV15.ps1';$provenance.laneCopyInitializer=Bound 'Research\Initialize-Gate13R36hLaneCopiesV15.ps1';$provenance.pilotOrchestrator=Bound 'Research\Run-Gate13R36hConcurrencyPilotV15.ps1';$provenance.pilotAnalyzer=Bound 'Research\Analyze-Gate13R36hConcurrencyPilotV15.ps1';$provenance.scheduleGenerator=Bound 'Research\Verification\New-Gate13R36hPilotScheduleV15.ps1';$provenance.staticUnitRunner=Bound 'Research\Verification\Run-Gate13R36hStaticUnitV15.ps1';$provenance.retainedRegressionRunner=Bound 'Research\Verification\Run-Gate13R36hRetainedRegressionV15.ps1';$provenance.verificationRunner=Bound 'Research\Verification\Run-Gate13R36hVerificationV15.ps1';$provenance.validationOnlyAuditRunner=Bound 'Research\Verification\Run-Gate13R36hValidationOnlyPrePilotAuditV15.ps1';$provenance.lockHygieneUnitRunner=Bound 'Research\Verification\Run-Gate13R36hLockHygieneUnitV15.ps1';$provenance.laneBootstrapRunner=Bound 'Research\Verification\Run-Gate13R36hLaneBootstrapCompileV15.ps1';$provenance.paths.verificationRoot='Research/Verification/Gate13R_36h_10pct_4Lane/v15';$provenance.paths.pilotRoot='Research/PilotRuns/Gate13R_36h_10pct_4Lane/v15';$provenance.paths.cloneRoot='H:/DDM_Final_Project_Gate13R36H/v15'
$bindings=[ordered]@{attempt13DerivationReceipt='Research\Gate13R_36h_10pct_4Lane_Attempt13_Derivation_Receipt.v1.json';attempt13BootstrapDiagnosis='Research\Gate13R_36h_10pct_4Lane_v13_Bootstrap_Log_Finalization_Diagnosis.v1.json';attempt14Amendment='Research\Gate13R_36h_10pct_4Lane_PrePilot_Defect_Repair_Amendment.v14.json';attempt14DerivationGenerator='Research\Verification\New-Gate13R36hAttempt14ArtifactsV1.ps1';attempt14Plan='Research\Gate13R_36h_10pct_4Lane_Pilot_Plan.v14.json';attempt14Schedule='Research\Gate13R_36h_10pct_4Lane_Pilot_Schedule.v14.json';attempt14ScheduleGeneration='Research\Gate13R_36h_10pct_4Lane_Pilot_Schedule_Generation.v14.json';attempt14DerivationManifest='Research\Gate13R_36h_10pct_4Lane_Attempt14_Derivation_Partial_Manifest.v1.json';attempt14DerivationFailure='Research\Gate13R_36h_10pct_4Lane_Attempt14_Derivation_Failure.v1.json';attempt14DerivationCheckpoint='Research\Gate13R_36h_10pct_4Lane_Attempt14_Derivation_Checkpoint.v1.json';attempt14DepthDiagnosis=$diagnosisRelative;attempt15Amendment=$amendmentRelative;attempt15DerivationGenerator=$generatorRelative}
foreach($entry in $bindings.GetEnumerator()){if($provenance.PSObject.Properties.Name-contains[string]$entry.Key){$provenance.([string]$entry.Key)=Bound ([string]$entry.Value)}else{$provenance|Add-Member -NotePropertyName ([string]$entry.Key) -NotePropertyValue (Bound ([string]$entry.Value))}}
